let payMonth='',payData=null,tgData=null,dailyReportDay='',payKpiVisibility=null,payKpiVisibilityError='';
const payKinds={work:'Сдельная работа',bonus:'Бонус',kpi:'KPI',fine:'Штраф',late:'Штраф за опоздание',advance:'Выданный аванс',payout:'Выплаченная зарплата'};
const cash=n=>(n/100).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2});
const cashInput=n=>(n/100).toFixed(2);
function defaultPayDate(m,d,next=false){let [y,mo]=m.split('-').map(Number);if(next){mo++;if(mo>12){y++;mo=1}}const last=new Date(Date.UTC(y,mo,0)).getUTCDate();return `${y}-${String(mo).padStart(2,'0')}-${String(Math.min(d,last)).padStart(2,'0')}`}
async function extraLoad(){if(tab==='payroll'){payMonth=payMonth||data.today.slice(0,7);payData=await api('payroll?month='+payMonth);await payrollVisibilityLoad();await payrollWorkflowLoad();if(globalThis.PayrollCenterUI)await globalThis.PayrollCenterUI.load(payMonth);if(data.user.admin&&typeof moyReload==='function')await moyReload();else if(typeof moyData!=='undefined')moyData=null}if(tab==='telegram'){const q=new URLSearchParams(dailyReportDay?{reportDay:dailyReportDay}:{});if(typeof attendanceToolsParams==='function')for(const [k,v] of Object.entries(attendanceToolsParams()))q.set(k,v);tgData=await api('telegram'+(q.size?'?'+q.toString():''));if(typeof telegramHistoryLoad==='function')await telegramHistoryLoad()}}
function payrollCarrySource(row){const from=row?.carryFrom||row?.account?.carryFrom;return /^\d{4}-(0[1-9]|1[0-2])$/.test(from||'')?`<span class="sub">Оклад перенесён из ${esc(from)}</span>`:''}
function payrollPriorBalances(rows){
 const list=Array.isArray(rows)?rows.filter(r=>/^\d{4}-(0[1-9]|1[0-2])$/.test(r.month||'')&&Number.isFinite(r.remaining)&&r.remaining!==0):[];
 if(!list.length)return '';
 return panel('Остатки прошлых месяцев',`<p class="help">Здесь сохранены непогашенные суммы за прошлые расчётные месяцы. Они не добавляются повторно к начислению текущего месяца. Выплату записывайте в том месяце, за который выдаёте зарплату.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Месяц</th><th>Сотрудник</th><th>Остаток</th><th>Валюта</th><th>Плановая дата зарплаты</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td>${esc(r.month)}</td><td>${esc(r.name||'')}</td><td><strong class="${r.remaining<0?'late':''}">${cash(r.remaining)}</strong>${r.remaining<0?'<span class="sub">Переплата — проверьте расчёт</span>':''}</td><td>${esc(r.currency)}</td><td>${esc(r.salaryDate||'—')}</td><td><button class="btn secondary" data-payroll-period="${esc(r.month)}">Открыть месяц</button></td></tr>`).join('')}</tbody></table></div>`);
}
function payrollPanel(){if(!payData)return empty('Загрузка расчётов','');const p=payData;return `<div class="row toolbar"><label>Расчётный месяц <input class="date" id="pay-month" type="month" value="${p.month}" min="2000-01" max="2100-12"></label>${button('Правила и даты выплат','pay-settings')}${payrollVisibilityButton()}</div><div class="notice">Выполненные работы + фиксированная часть + бонусы + KPI − штрафы − выданные авансы − выплаченная зарплата. Отрицательный остаток показывается как переплата и требует проверки. Плановая дата не создаёт выплату.</div>${payrollPriorBalances(p.priorBalances)}${panel('Расчётная ведомость · '+esc(p.settings.currency),p.rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Сотрудник</th><th>Работы + фикс.</th><th>Бонусы + KPI</th><th>Штрафы</th><th>Выдано</th><th>Остаток</th><th></th></tr></thead><tbody>${p.rows.map(r=>`<tr><td><span class="name">${esc(r.employee.name)}</span><span class="sub">${r.account?'Аванс '+r.account.advance_date+' · зарплата '+r.account.salary_date:'Расчёт ещё не настроен'}</span>${payrollCarrySource(r)}${payrollTurnoverSummary(r.turnoverKpi||r.latestTurnoverKpi,!r.turnoverKpi)}</td><td>${cash(r.totals.base+r.totals.work)}</td><td>${cash(r.totals.bonus+r.totals.kpi)}</td><td>${cash(r.totals.fine+r.totals.late)}</td><td>${cash(r.totals.advance+r.totals.payout)}</td><td><strong class="${r.totals.remaining<0?'late':''}">${cash(r.totals.remaining)}</strong></td><td>${button(r.account?'Подробности':'Настроить расчёт','pay-detail',`data-employee="${r.employee.id}"`,!r.account)}</td></tr>`).join('')}</tbody></table></div>`:empty('Добавьте сотрудников','Команда создаётся в разделе «Сотрудники».'))}<p class="help">Работы начисляются после подтверждения количества и цены. Налоги и обязательные взносы не рассчитываются. Подтверждайте удержания по применимым правилам вашей организации.</p>`+payrollWorkflowPanel()+(globalThis.PayrollCenterUI?.panel?.()||'')+(typeof moyskladPanel==='function'?moyskladPanel():'')}
function payRow(id){return payData.rows.find(r=>r.employee.id===id)}
function payrollTurnoverExcluded(k){return k?.excluded===true||k?.status==='excluded';}
function payrollTurnoverRedistribution(k){const r=k?.redistribution;if(!r||r.method!=='proportional'||payrollTurnoverExcluded(k))return '';const amount=value=>Number.isSafeInteger(value)?cash(value)+' '+esc(k.currency||'UZS'):'Ожидает данных';return `<p class="help">В том числе после пропорционального перераспределения: +${amount(r.addedMaximum)} к максимуму; ${Number.isSafeInteger(r.addedProposal)?'+':''}${amount(r.addedProposal)} к проекту премии.</p>`;}
function payrollTurnoverCard(k,latest=false){if(!k)return '';if(payrollTurnoverExcluded(k))return `<section class="pay-record turnover-kpi-card"><h3>Командный KPI оборота</h3>${latest?`<p class="help">Последний расчёт ${esc(k.month)} · отдельно от текущего месяца</p>`:''}<p>${esc(k.month)} · ${badge('Исключён из командного KPI','blue')}</p><p>Не участвует в командном расчёте за этот месяц. Оценка результативности не выставлена.</p>${k.reason?'<p class="help">'+esc(k.reason)+'</p>':''}</section>`;const amount=value=>Number.isSafeInteger(value)?cash(value)+' '+esc(k.currency||'UZS'):'Ожидает данных',score=typeof k.score==='number'&&Number.isFinite(k.score)?k.score.toLocaleString('ru-RU',{maximumFractionDigits:2})+'%':'Ожидает источника';return `<section class="pay-record turnover-kpi-card"><h3>Командный KPI оборота</h3>${latest?`<p class="help">Последний расчёт ${esc(k.month)} · отдельно от текущего месяца</p>`:''}<p>${esc(k.month)} / ${esc(k.basisMonth||'—')} · ${badge(k.posted?'Начислено':'Проект · не начислено',k.posted?'good':'blue')}</p><p><strong>${score}</strong> · ${k.posted?'начислено':'проект премии'} <strong>${amount(k.proposal)}</strong></p><p>Диапазон: ${amount(k.minimum)} — ${amount(k.maximum)}</p><p class="help">Ретроспективное сравнение оборота всей команды с предыдущим месяцем. Должностной KPI оценивается отдельно. ${k.posted?'Премия включена в начисления. Фактическая выплата фиксируется отдельно.':'Проект не включён в остаток зарплаты.'}</p>${payrollTurnoverRedistribution(k)}${k.accountConfigured===false?'<p class="notice">Расчёт зарплаты за этот месяц не настроен.</p>':''}${k.capBasis==='role-benchmark'?'<p class="help">Максимум предложен по ориентиру должности.</p>':''}${k.reason?'<p class="notice">'+esc(k.reason)+'</p>':''}</section>`;}
function payrollTurnoverSummary(k,latest=false){if(!k)return '';if(payrollTurnoverExcluded(k))return `<span class="sub">${latest?'Последний расчёт ':''}${esc(k.month)} · Не участвует в командном KPI</span>`;const score=typeof k.score==='number'&&Number.isFinite(k.score)?k.score.toLocaleString('ru-RU',{maximumFractionDigits:2})+'%':'ожидает данных',amount=Number.isSafeInteger(k.proposal)?cash(k.proposal)+' '+esc(k.currency||'UZS'):'ожидает данных';return `<span class="sub">${latest?'Последний расчёт '+esc(k.month)+' · ':esc(k.month)+' · '}Командный KPI: ${score} · проект ${amount}</span>`;}
function payDetail(id){const r=payRow(id);if(!r.account){if(!r.turnoverKpi&&!r.latestTurnoverKpi)return payAccount(id);open(esc(r.employee.name)+' · '+payMonth,`<div class="pay-detail">${payrollTurnoverCard(r.turnoverKpi||r.latestTurnoverKpi,!r.turnoverKpi)}${button('Настроить расчёт зарплаты','pay-account',`data-employee="${id}"`)}</div>`);extraBind(modal);return;}const t=r.totals;open(esc(r.employee.name)+' · '+payMonth,`<div class="pay-detail">${payrollPriorBalances(r.priorBalances)}${payrollCarrySource(r)}${payrollTurnoverCard(r.turnoverKpi||r.latestTurnoverKpi,!r.turnoverKpi)}<div class="pay-total"><span>${t.remaining<0?'Переплата / к проверке':'Осталось получить'}</span><strong>${cash(t.remaining)} ${esc(r.account.currency)}</strong></div><div class="row">${button('Фиксированная часть и даты','pay-account',`data-employee="${id}"`)}${button('История должности и ставки','pay-history',`data-employee="${id}"`)}${button('+ Выполненная работа','pay-job',`data-employee="${id}"`,false)}${button('+ Операция','pay-entry',`data-employee="${id}"` ,false)}${button('+ Показатель KPI','pay-kpi',`data-employee="${id}"`)}</div>${typeof moyskladEmployee==='function'?moyskladEmployee(id):''}<h3>Начисления и выплаты</h3><div class="table-wrap"><table class="data-table"><tbody><tr><td>Выполненные работы</td><td>${cash(t.work)}</td></tr><tr><td>Фиксированная часть</td><td>${cash(t.base)}</td></tr><tr><td>Бонусы + KPI</td><td>+ ${cash(t.bonus+t.kpi)}</td></tr><tr><td>Штрафы + опоздания</td><td>− ${cash(t.fine+t.late)}</td></tr><tr><td>Авансы</td><td>− ${cash(t.advance)}</td></tr><tr><td>Выплаченная зарплата</td><td>− ${cash(t.payout)}</td></tr></tbody></table></div><h3>Выполненные работы</h3>${r.jobs.map(j=>`<div class="pay-record"><strong>${esc(j.name)}</strong><p>${j.date} · ${cash(j.quantity)} ${esc(j.unit)} × ${cash(j.rate)} = ${cash(j.calculated)} ${esc(r.account.currency)}</p>${j.posted?badge('Начислено','good'):`<div class="row">${button('Изменить','pay-job',`data-employee="${id}" data-id="${j.id}"`)}${button('Подтвердить работу','pay-approve-job',`data-employee="${id}" data-id="${j.id}"`)}</div>`}</div>`).join('')||'<p class="help">Добавьте выполненную работу, количество и цену за единицу.</p>'}<h3>Показатели KPI</h3>${r.metrics.map(k=>`<div class="pay-record"><strong>${esc(k.name)}</strong><p>План ${cash(k.target)} · факт ${cash(k.actual)} · ${k.score}%</p><p>Бонус ${cash(k.calculated)} из ${cash(k.max_bonus)} ${esc(r.account.currency)}</p>${k.posted?badge('Начислен','good'):`<div class="row">${button('Изменить','pay-kpi',`data-employee="${id}" data-id="${k.id}"`)}${k.calculated>0?button('Подтвердить бонус','pay-approve-kpi',`data-employee="${id}" data-id="${k.id}"`):''}</div>`}</div>`).join('')||'<p class="help">KPI пока не заданы.</p>'}<h3>Опоздания — на подтверждение</h3><p class="help">Правило: ${cash(payData.settings.lateRate)} ${esc(payData.settings.currency)} ${payData.settings.lateMode==='minute'?'за минуту':'за случай'}. Учитываются опоздания сверх допуска смены.</p>${r.lateCandidates.map(l=>`<div class="pay-record"><strong>${l.day} · ${l.minutes} мин · ${cash(l.amount)}</strong>${l.excused?badge('Согласованное отсутствие: проверить старые штрафы','blue'):''}${l.posted?badge('Штраф подтверждён','warn'):l.amount>0?button('Подтвердить штраф','pay-late',`data-employee="${id}" data-shift="${l.shift}"`):badge(l.excused?'Начисление заблокировано':'Ставка не задана')}</div>`).join('')||'<p class="help">Опозданий за этот месяц нет.</p>'}<h3>История операций</h3>${r.entries.map(e=>`<div class="pay-record ${e.voided_at?'voided':''}"><strong>${payKinds[e.kind]} · ${cash(e.amount)} ${esc(r.account.currency)}</strong><p>${esc(e.date)} · ${esc(e.reason)}</p>${e.voided_at?`<p>Отменено: ${esc(e.void_reason)}</p>`:button('Отменить запись','pay-void',`data-id="${e.id}"`)}</div>`).join('')||'<p class="help">Операций пока нет.</p>'}<details><summary>Изменения оклада и операций</summary>${payData.audit.filter(a=>a.employee===id).map(a=>`<p class="help">${esc(stamp(a.at))} · ${esc({account:'Оклад / даты',entry:'Новая операция',void:'Отмена операции',kpi:'Изменение KPI',job:'Выполненная работа'}[a.action]||a.action)}</p>`).join('')}</details></div>`);extraBind(modal)}
function submitPay(path,extra,after){const f=modal.querySelector('form');const requestId=crypto.randomUUID();f.onsubmit=async ev=>{ev.preventDefault();const values=Object.fromEntries(new FormData(f));if(await mutate(path,{...extra,...values,requestId})){modal.close();toast('Сохранено');after?.()}}}
function payAccount(id){const r=payRow(id),a=r.account,c=payData.settings;open('Фиксированная часть и даты · '+esc(r.employee.name),`<form class="form"><p>Расчётный месяц: ${payMonth}. Валюта: ${esc(c.currency)}.</p><label>Фиксированная часть за месяц (необязательно)<input name="base" type="number" step="0.01" min="0" max="9999999999.99" value="${cashInput(a?.base||0)}" required></label><label>Дата начала ставки<input name="effectiveDate" type="date" required value="${payMonth+'-01'}"></label><p class="help">Сумма — база выбранного месяца. Дата фиксирует начало согласованного изменения; перерасчёт по дням автоматически не выполняется.</p><label>Основание изменения<textarea name="reason" required minlength="3" maxlength="500"></textarea></label><label>Плановая дата аванса<input name="advanceDate" type="date" value="${a?.advance_date||defaultPayDate(payMonth,c.advanceDay)}" required></label><label>Плановая дата зарплаты<input name="salaryDate" type="date" value="${a?.salary_date||defaultPayDate(payMonth,c.salaryDay,true)}" required></label><p class="help">При сдельной оплате оставьте 0. Заработок за выполненные работы начисляется отдельно после подтверждения.</p><button class="btn">Сохранить начисление и даты</button></form>`);submitPay('payroll/account',{employee:id,month:payMonth})}
function payEntry(id){open('Начисление или выплата',`<form class="form"><label>Тип операции<select name="kind"><option value="bonus">Бонус</option><option value="fine">Подтверждённый штраф</option><option value="advance">Аванс — деньги уже выданы</option><option value="payout">Зарплата — деньги уже выплачены</option></select></label><label>Сумма, ${esc(payData.settings.currency)}<input name="amount" type="number" step="0.01" min="0.01" max="9999999999.99" required></label><label>Дата фактической операции<input name="date" type="date" value="${data.today}" max="${data.today}" required></label><label>Основание / комментарий<textarea name="reason" maxlength="300" required></textarea></label><p class="help">Авансы и выплаты уменьшают остаток. Здесь фиксируется факт выдачи денег; банковский перевод не выполняется.</p><button class="btn">Записать операцию</button></form>`);submitPay('payroll/entry',{employee:id,month:payMonth})}
function payKpi(id,kid){const k=payRow(id).metrics.find(k=>k.id===kid);open(k?'Изменить KPI':'Показатель KPI',`<form class="form"><label>Название показателя<input name="name" maxlength="100" value="${esc(k?.name||'')}" placeholder="Например, выполнение плана продаж" required></label><label>План<input name="target" type="number" min="0.01" step="0.01" value="${cashInput(k?.target||10000)}" required></label><label>Факт<input name="actual" type="number" min="0" step="0.01" value="${cashInput(k?.actual||0)}" required></label><label>Максимальный бонус, ${esc(payData.settings.currency)}<input name="maxBonus" type="number" min="0" step="0.01" value="${cashInput(k?.max_bonus||0)}" required></label><p class="help">Бонус = максимум × факт / план, но не выше максимума. После сохранения расчёт нужно подтвердить отдельно.</p><button class="btn">Сохранить KPI</button></form>`);submitPay('payroll/kpi',{employee:id,month:payMonth,id:kid})}
function paySettings(){const c=payData.settings;open('Правила расчётов и выплат',`<form class="form"><label>Валюта<select name="currency">${['UZS','RUB','USD','EUR','KZT'].map(x=>`<option ${c.currency===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="split"><label>Число аванса (текущий месяц)<input name="advanceDay" type="number" min="1" max="31" value="${c.advanceDay}" required></label><label>Число зарплаты (следующий месяц)<input name="salaryDay" type="number" min="1" max="31" value="${c.salaryDay}" required></label></div><label class="row"><input name="autoCarryForward" type="checkbox" ${c.autoCarryForward===true?'checked':''}> Автоматически переносить оклады в новый месяц</label><p class="help">Переносятся фиксированная часть и новые плановые даты выплат. Выполненные работы, премии, штрафы, авансы и остатки прошлых месяцев сохраняются в своих периодах.</p><label>Правило штрафа за опоздание<select name="lateMode"><option value="minute" ${c.lateMode==='minute'?'selected':''}>За каждую минуту</option><option value="incident" ${c.lateMode==='incident'?'selected':''}>За каждый случай</option></select></label><label>Ставка штрафа<input name="lateRate" type="number" min="0" step="0.01" value="${cashInput(c.lateRate)}" required></label><p class="help">0 отключает расчёт штрафов. Штрафы применяются после ручного подтверждения. Новая ставка меняет только ещё не подтверждённые расчёты.</p><p class="help">Аванс — ${esc(c.advanceDay)}-го числа текущего расчётного месяца, зарплата — ${esc(c.salaryDay)}-го числа следующего месяца. Например, за ноябрь при датах 25 и 10: аванс 25 ноября, зарплата 10 декабря. Даты — шаблон для новых расчётов. Если такого числа в месяце нет, выбирается последний день. Валюта фиксируется после создания первого расчёта.</p><button class="btn">Сохранить правила</button></form>`);const f=modal.querySelector('form');f.onsubmit=async ev=>{ev.preventDefault();const v=Object.fromEntries(new FormData(f));if(await mutate('payroll/settings',{...v,advanceDay:Number(v.advanceDay),salaryDay:Number(v.salaryDay),autoCarryForward:f.elements.autoCarryForward.checked===true})){modal.close();toast('Правила сохранены')}}}
function telegramAttendanceBindings(){const a=tgData.attendance||{},bindings=Array.isArray(a.bindings)?a.bindings:[];return `<h3>Привязка к боту прихода и ухода</h3><p class="help">Здесь подтверждается только учёт смен. Приглашение и отзыв привязки не меняют доступ к зарплатному боту. Подтверждённые аккаунты сотрудников могли быть перенесены при обновлении; остальные привязываются отдельно.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Сотрудник</th><th>Telegram</th><th>Статус</th><th>Действия</th></tr></thead><tbody>${data.employees.filter(e=>e.active).map(e=>{const b=bindings.find(x=>x.employee===e.id);return `<tr><td class="name">${esc(e.name)}</td><td>${b?esc(b.username)+'<span class="sub">ID '+esc(b.chat)+'</span>':'—'}</td><td>${badge(!b?'Не привязан':b.status==='approved'?'Подтверждён':'Ожидает проверки',b?.status==='approved'?'good':'')}</td><td><div class="row">${!b?button('Личная ссылка для смен','tga-invite',`data-employee="${e.id}" ${a.connected?'':'disabled'}`):`${b.status==='pending'?button('Подтвердить для смен','tga-approve',`data-employee="${e.id}"`):''}${button('Отвязать от смен','tga-unlink',`data-employee="${e.id}"`)}`}</div></td></tr>`}).join('')}</tbody></table></div>`}
function telegramAttendancePanel(){
 const bot=tgData.attendance||{},a=bot.group||{},username=/^[A-Za-z0-9_]{5,32}$/.test(bot.username||'')?bot.username:/^[A-Za-z0-9_]{5,32}$/.test(bot.expectedUsername||'')?bot.expectedUsername:'Davomat';
 return panel('Бот прихода и ухода',`<p>Отдельный бот для видео у двери, открытия и закрытия смен. Зарплата и анкеты кандидатов работают в своих ботах.</p><div class="split"><form class="form" id="telegram-attendance-bot-form">${badge(bot.connected?'Подключён: @'+esc(username):'Бот смен не подключён',bot.connected?'good':'warn')}<p>Бот смен: <strong>@${esc(username)}</strong>. Получите его токен в <a href="https://t.me/BotFather" target="_blank" rel="noreferrer">@BotFather</a> и вставьте здесь. Не используйте токен зарплатного бота или бота анкет.</p><label>Токен бота прихода и ухода<input type="password" name="token" autocomplete="new-password" required placeholder="Токен отдельного бота из BotFather"></label><button class="btn">Подключить бота смен</button>${bot.connected?button('Отключить бота смен','tga-disconnect'):''}${bot.lastError?`<p class="error" role="alert">${esc(bot.lastError)}</p>`:''}<p class="help">${bot.lastSeen?'Последняя связь: '+esc(stamp(bot.lastSeen)):'Связь с ботом смен ещё не проверена.'} Токен вводится только здесь, в чат его отправлять не нужно.</p></form><div class="form"><h3>Подключение рабочей группы</h3><ol><li>Подключите отдельного бота смен в форме слева, затем добавьте <strong>@${esc(username)}</strong> в рабочую группу. Дайте права администратора либо отключите Privacy Mode через @BotFather, чтобы он получал видео.</li><li>Отправьте в группе <code>/groupid@${esc(username)}</code> и скопируйте ID из личного ответа бота в настройку ниже.</li><li>Проверьте привязки сотрудников в таблице «Привязка к боту прихода и ухода». Для новых привязок сотрудник открывает личную ссылку в личном чате с ботом смен и ждёт подтверждения администратора.</li></ol><p class="help">Бот смен обрабатывает приход и уход. Зарплата, бонусы и штрафы остаются в зарплатном боте; в группе финансовые данные не публикуются.</p></div></div><div class="split"><form class="form" id="telegram-attendance-form">${badge(a.enabled?'Приём видео включён':'Приём видео выключен',a.enabled?'good':'')}${!bot.connected?'<p class="notice">Сначала подключите отдельного бота прихода и ухода. После подключения можно включить приём видео.</p>':''}<label class="row"><input name="enabled" type="checkbox" ${a.enabled?'checked':''} ${bot.connected?'':'disabled'}> Учитывать приход и уход из группы</label><label>ID рабочей группы<input name="groupId" type="text" inputmode="text" pattern="-[0-9]+" maxlength="24" value="${esc(a.groupId||'')}" placeholder="Например, -1001234567890" ${a.enabled?'required':''}></label><label>Как выбирать отметку<select name="mode"><option value="confirm" ${a.mode!=='auto'?'selected':''}>Сотрудник выбирает «Пришёл» / «Ушёл»</option><option value="auto" ${a.mode==='auto'?'selected':''}>Автоматически по времени графика</option></select></label><p class="help">С подписью «Пришёл» или «Ушёл» отметка выбирается сразу. Для видеокружка бот предлагает кнопки автору в личном чате. Подтверждение открытия смены и минуты опоздания, а также подтверждение закрытия смены бот публикует в рабочей группе ответом на видео сотрудника. Напоминания, заявки и кнопки приходят в личку. Каждому сотруднику и ответственному нужно открыть бота и нажать «Старт». Подписи поддерживаются на русском, узбекском и таджикском: Пришёл / Keldim / Омадам и Ушёл / Ketdim / Рафтам.</p><button class="btn">Сохранить приём видео</button>${a.lastError?`<p class="error" role="alert">${esc(a.lastError)}</p>`:''}${a.privateWaiting?`<p class="notice">Ожидают личной доставки: ${esc(a.privateWaiting)}. Сотруднику нужно разблокировать бота и отправить /start. Сообщения в группу не пересылаются.</p>`:''}${Number.isFinite(a.storage?.freeBytes)?`<p class="help">На сервере свободно ${(a.storage.freeBytes/1073741824).toLocaleString('ru-RU',{maximumFractionDigits:1})} ГБ. Для работы сервера сохраняется резерв 1 ГБ. Старые видео автоматически не удаляются.</p>`:''}<p class="help">До ${esc(a.maxVideoMB||20)} МБ. Видео сохраняется в закрытом хранилище и доступно в журнале смен и ежедневном отчёте по правам доступа.</p></form><div class="form"><h3>Видео у двери магазина</h3><p>Сотрудник снимает короткое видео у двери магазина при приходе и уходе. Время отметки — время отправки сообщения в Telegram.</p><p class="help">Лицо и место съёмки автоматически не проверяются. Пересланное видео и сообщения старше 10 минут не принимаются. Повторная отправка не открывает вторую смену.</p><details><summary>Как работает автоматический режим</summary><p class="help">Приход: от 3 часов до начала до 4 часов после начала смены. Уход: от 3 часов до конца до 6 часов после конца смены, после минимум 60 минут работы. Вне этих окон сотрудник выбирает отметку кнопкой. Действует график программы, включая ночные смены.</p></details><p class="help">Опоздания, ранний уход и месячная дисциплина считаются по этим же отметкам. Уважительную причину можно указать в разделе «Дисциплина и KPI»; денежные удержания подтверждаются отдельно.</p></div></div>${geofencePanel(a.geofence)}${videoRetryPanel(a.videoRetry)}${telegramAttendanceBindings()}`)
}
function dailyReportsPanel(){const d=tgData?.dailyReports;if(!d)return '';const labels={pending:'Ожидает отправки',sending:'Отправляется',sent:'Доставлено',blocked:'Нужна настройка',cancelled:'Отменено',uncertain:'Проверьте доставку'};const selected=d.employees.filter(e=>d.recipients.includes(e.id));return panel('Ежедневный отчёт руководителям',`<div class="daily-report-body"><p>Бот прихода и ухода отправит полный отчёт лично выбранным руководителям: приход, уход, опоздания, перерывы, ранний уход и кто подтвердил разрешение. Выходные и отсутствие отметок тоже будут видны.</p><form class="form" id="daily-report-settings"><label><input type="checkbox" name="enabled" ${d.settings.enabled?'checked':''}> Отправлять ежедневно</label><div class="row"><label>Время отправки (${esc(d.timezone)})<input type="time" name="time" value="${esc(d.settings.time)}" required></label><label>За какой день<select name="period"><option value="today" ${d.settings.period==='today'?'selected':''}>За текущий день</option><option value="previous" ${d.settings.period==='previous'?'selected':''}>За предыдущий день</option></select></label></div><h3>Кому отправлять полный отчёт</h3><p class="help">Отметьте руководителей из базы. Ниже в «Привязка к боту прихода и ухода» можно создать личную ссылку и подтвердить их профиль. Руководитель должен нажать «Старт» в Davomat.</p>${d.employees.map(e=>`<label class="check"><input type="checkbox" name="recipient" value="${esc(e.id)}" ${d.recipients.includes(e.id)?'checked':''}> ${esc(e.name)} — ${e.ready?'Telegram подтверждён':esc(e.reason||'Нужна привязка')}</label>`).join('')}<button class="btn">Сохранить получателей и время</button><p class="help">После сохранения, если время уже прошло, отправка начнётся автоматически. Для ночных смен выбирайте предыдущий день и время после окончания смены.</p></form><h3>Предпросмотр и доставка</h3><label class="daily-report-date">Дата отчёта<input id="daily-report-day" type="date" value="${esc(d.day)}" max="${esc(d.today)}"></label><p>Получатели: ${esc(selected.map(e=>e.name).join(', ')||'Не назначены')}</p><pre class="ops-digest">${esc(d.report.messages.join('\n\n'))}</pre>${button('Отправить отчёт за выбранный день','tga-daily-send',d.settings.enabled&&selected.length?'':'disabled')}<p class="help">Один отчёт на получателя за дату. Повторное нажатие и перезапуск сервера не создают дубликатов. Отправленный отчёт сохраняет данные на момент формирования; дальнейшие исправления видны на сайте.</p>${hrTable(['Руководитель','Часть','Доставка','Действия'],d.deliveries.map(r=>[esc(r.name),`${r.part}/${r.total}`,badge(labels[r.status]||r.status,r.status==='sent'?'good':'warn')+'<span class="sub">'+esc(r.error||'')+'</span>',['blocked','cancelled'].includes(r.status)?button('Повторить неотправленное','tga-daily-retry',`data-employee="${esc(r.employee)}" data-day="${esc(r.day)}"`):'']))}</div>`)}
function excelReportsPanel(){const e=tgData?.excelReports,d=tgData?.dailyReports;if(!e||!d)return '';const labels={pending:'В очереди',sending:'Отправляется',sent:'Доставлено',blocked:'Нужна настройка',cancelled:'Отменено',uncertain:'Проверьте Telegram'};return panel('Excel после закрытия смены',`<div class="daily-report-body"><p>После закрытия смены бот пришлёт выбранным руководителям файл со всеми сотрудниками за день: план, приход, уход, отработанные минуты, перерывы, опоздания и разрешения раннего ухода.</p><form class="form" id="shift-excel-settings"><label class="check"><input type="checkbox" name="enabled" ${e.settings.enabled?'checked':''}> Отправлять Excel руководителям</label><label>Когда отправлять<select name="mode"><option value="each" ${e.settings.mode==='each'?'selected':''}>После каждого закрытия смены</option><option value="all" ${e.settings.mode==='all'?'selected':''}>Когда все смены за день закрыты</option></select></label><p class="help">Получатели — руководители, выбранные ниже в ежедневных отчётах. Файл приходит лично в Davomat. Получателей: ${esc(e.recipients)}. Режим «Все смены» ждёт отметок ухода у всех сотрудников по графику, включая ночные смены. Отсутствующие отметки остановят итоговую отправку.</p><button class="btn">Сохранить отправку Excel</button></form><p>Настройки действуют для новых закрытий смен. Сохранённые файлы отражают данные на момент закрытия. Открытые смены в них предварительные.</p><label class="daily-report-date">Дата Excel-отчёта<input id="shift-excel-day" type="date" value="${esc(d.day)}" max="${esc(d.today)}"></label><a class="btn secondary" href="/api/telegram/attendance/excel?day=${encodeURIComponent(d.day)}">Скачать Excel за ${esc(d.day)}</a><p class="help">Скачивание формирует актуальные данные за выбранную дату и не отправляет сообщения.</p>${e.deliveries.length?hrTable(['Руководитель','Закрытие смены','Доставка','Действия'],e.deliveries.map(r=>[esc(r.name),esc(time(r.created)),badge(labels[r.status]||r.status,r.status==='sent'?'good':'warn')+'<span class="sub">'+esc(r.error||'')+'</span>',['blocked','cancelled'].includes(r.status)?button('Повторить неотправленный Excel','tga-excel-retry',`data-employee="${esc(r.employee)}" data-snapshot="${esc(r.snapshot)}"`):''])):'<p class="help">После нового закрытия смены здесь появятся статусы доставки Excel руководителям.</p>'}</div>`)}
function earlyExitPanel(){const e=tgData?.earlyExit;if(!e)return '';const labels={pending:'Ожидает подтверждения',approved:'Разрешение подтверждено',rejected:'Разрешение не подтверждено'};return panel('Ранний уход по разрешению',`<p>При видео ухода до конца смены бот предложит «Ушёл» или «По разрешению». Сотрудник выбирает ответственного из списка ниже. Смена закрывается по времени видео; заявку и кнопки подтверждения получает только выбранный ответственный в личном чате бота. Решение приходит сотруднику в личку.</p><form class="form" id="early-exit-settings"><label><input name="enabled" type="checkbox" ${e.enabled?'checked':''}> Включить выбор разрешения раннего ухода</label><h3>Кто может разрешать ранний уход</h3><p class="help">Выберите сотрудников из базы. Для подтверждения в личном чате нужна их подтверждённая привязка к боту смен и нажатие «Старт». Администратор также может рассмотреть заявку здесь с указанием основания.</p>${e.employees.map(r=>`<label class="check"><input type="checkbox" name="responsible" value="${esc(r.id)}" ${e.responsibles.includes(r.id)?'checked':''}> ${esc(r.name)}${r.telegramReady?'':' — Telegram не привязан'}</label>`).join('')}<button class="btn">Сохранить ответственных</button></form><h3>Разрешения и решения</h3><p class="help">Подтверждённый уход исключается только из расчёта раннего ухода в дисциплине. Уже начисленные суммы автоматически не изменяются.</p>${hrTable(['Сотрудник / дата','Время / ответственный','Статус','Действия'],e.requests.map(r=>[esc(r.name)+'<span class="sub">'+esc(r.day)+'</span>',esc(time(r.at))+' / план '+esc(time(r.planned_end))+'<span class="sub">'+esc(r.responsible_name)+'</span>',badge(labels[r.status]||r.status,r.status==='approved'?'good':'warn')+'<span class="sub">'+esc(r.decision_name||'')+'</span>'+(r.posted?'<span class="sub">Начисления месяца подтверждены: проверьте корректировку.</span>':''),(r.video?`<a class="btn secondary" target="_blank" rel="noreferrer" href="/api/attendance-video?id=${encodeURIComponent(r.video)}">Видео ухода</a>`:'')+(r.status==='pending'?button('Подтвердить','tga-early-decision',`data-token="${esc(r.token)}" data-status="approved"`)+button('Отклонить','tga-early-decision',`data-token="${esc(r.token)}" data-status="rejected"`):'')]))}`)}
function telegramPanel(){if(!tgData)return empty('Загрузка Telegram','');return (typeof latePermissionPanel==='function'?latePermissionPanel():'')+(typeof storeExcellencePanel==='function'?storeExcellencePanel():'')+(typeof attendanceToolsPanel==='function'?attendanceToolsPanel():'')+(typeof shiftBotPanel==='function'?shiftBotPanel():'')+(typeof telegramHistoryPanel==='function'?telegramHistoryPanel():'')+excelReportsPanel()+dailyReportsPanel()+noticesPanel()+`<div class="split">${panel('Зарплатный бот',`<form class="form" id="telegram-form">${badge(tgData.connected?'Подключён: @'+tgData.username:'Не подключён',tgData.connected?'good':'warn')}<p>Создайте отдельного бота через <a href="https://t.me/BotFather" target="_blank" rel="noreferrer">@BotFather</a> и вставьте токен здесь. В чат с помощником токен отправлять не нужно.</p><label>Токен бота<input type="password" name="token" autocomplete="new-password" required placeholder="Токен из BotFather"></label><button class="btn">Подключить бота</button>${tgData.connected?button('Отключить','tg-disconnect'):''}${tgData.lastError?`<p class="error">${esc(tgData.lastError)}</p>`:''}<p class="help">${tgData.lastSeen?'Последняя связь: '+stamp(tgData.lastSeen):'Связь с Telegram ещё не проверена.'}</p><p class="help">Бот отвечает, пока сервер включён и имеет доступ к интернету. Не запускайте этого же бота одновременно в другой программе.</p></form>`)}${panel('Что видит сотрудник',`<div class="form"><p>Только свои данные за выбранный месяц: выполненные работы, фиксированная часть, бонусы, KPI, штрафы, авансы и остаток.</p><p>Команды: /profile, /salary, /bonuses, /fines, /advances, /work, /kpi, /dates, /tasks, /leave.</p><p>Пример: /salary 2026-10</p><p class="help">Личные данные не отправляются в группы. После перехода по ссылке сотрудник ждёт вашего подтверждения.</p></div>`)}</div>${telegramAttendancePanel()}${earlyExitPanel()}${panel('Доступ к зарплатному боту',`<div class="table-wrap"><table class="data-table"><thead><tr><th>Сотрудник</th><th>Telegram</th><th>Статус</th><th>Действия</th></tr></thead><tbody>${data.employees.filter(e=>e.active).map(e=>{const b=tgData.bindings.find(x=>x.employee===e.id);return `<tr><td class="name">${esc(e.name)}</td><td>${b?esc(b.username)+'<span class="sub">ID '+esc(b.chat)+'</span>':'—'}</td><td>${badge(!b?'Не привязан':b.status==='approved'?'Подтверждён':'Ожидает проверки',b?.status==='approved'?'good':'')}</td><td><div class="row">${!b?button('Создать личную ссылку','tg-invite',`data-employee="${e.id}"`):`${b.status==='pending'?button('Подтвердить личность','tg-approve',`data-employee="${e.id}"`):''}${button('Отвязать','tg-unlink',`data-employee="${e.id}"`)}`}</div></td></tr>`}).join('')}</tbody></table></div>`,button('Обновить','tg-refresh'))}`}
function extraBind(scope=document){globalThis.PayrollCenterUI?.bind?.(scope);scope.querySelectorAll('[data-payroll-period]').forEach(b=>b.onclick=async()=>{const period=b.dataset.payrollPeriod;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period||''))return;payMonth=period;modal.close();try{await load()}catch(e){toast(e.message)}});if(typeof bindMoysklad==='function')bindMoysklad(scope);if(typeof bindLatePermission==='function')bindLatePermission(scope);if(typeof bindStoreExcellence==='function')bindStoreExcellence(scope);if(typeof bindAttendanceTools==='function')bindAttendanceTools(scope);const gf=scope.querySelector('#attendance-geofence-form');if(gf)gf.onsubmit=async ev=>{ev.preventDefault();const e=gf.elements;const number=k=>e[k].value.trim()===''?null:Number(e[k].value);if(await mutate('telegram/attendance/geofence',{revision:tgData.attendance.group.geofence.revision,enabled:e.enabled.checked,latitude:number('latitude'),longitude:number('longitude'),radius:number('radius'),maxAccuracy:number('maxAccuracy'),requireAccuracy:e.requireAccuracy.checked,label:e.label.value,sourceUrl:e.sourceUrl.value}))toast('Территория магазина сохранена');};if(typeof bindShiftBot==='function')bindShiftBot(scope);if(typeof bindTelegramHistory==='function')bindTelegramHistory(scope);const xd=scope.querySelector('#shift-excel-day');if(xd)xd.onchange=async()=>{if(!xd.value)return;dailyReportDay=xd.value;try{await load()}catch(e){toast(e.message)}};const xf=scope.querySelector('#shift-excel-settings');if(xf)xf.onsubmit=async ev=>{ev.preventDefault();const f=new FormData(xf);if(await mutate('telegram/attendance/excel/settings',{enabled:f.has('enabled'),mode:f.get('mode')}))toast('Отправка Excel сохранена')};const df=scope.querySelector('#daily-report-settings');if(df)df.onsubmit=async ev=>{ev.preventDefault();const f=new FormData(df);if(await mutate('telegram/attendance/daily-reports/settings',{enabled:f.has('enabled'),time:f.get('time'),period:f.get('period'),recipients:f.getAll('recipient')}))toast('Время и получатели ежедневных отчётов сохранены')};const dd=scope.querySelector('#daily-report-day');if(dd)dd.onchange=async()=>{if(!dd.value)return;dailyReportDay=dd.value;try{await load()}catch(e){toast(e.message)}};const ef=scope.querySelector('#early-exit-settings');if(ef)ef.onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ef);if(await mutate('telegram/attendance/early-exit/settings',{enabled:f.has('enabled'),responsibles:f.getAll('responsible')}))toast('Ответственные за ранний уход сохранены')};scope.querySelectorAll('[data-action^="pay-"],[data-action^="tg-"],[data-action^="tga-"]').forEach(b=>b.onclick=()=>extraAct(b.dataset));const month=scope.querySelector('#pay-month');if(month)month.onchange=async()=>{if(!month.value)return;payMonth=month.value;try{await load()}catch(e){toast(e.message)}};const form=scope.querySelector('#telegram-form');if(form)form.onsubmit=async ev=>{ev.preventDefault();if(await mutate('telegram/connect',{token:form.elements.token.value})){form.reset();toast('Бот подключён')}};const attendanceBotForm=scope.querySelector('#telegram-attendance-bot-form');if(attendanceBotForm)attendanceBotForm.onsubmit=async ev=>{ev.preventDefault();if(await mutate('telegram/attendance/connect',{token:attendanceBotForm.elements.token.value})){attendanceBotForm.reset();toast('Бот прихода и ухода подключён')}};const attendanceForm=scope.querySelector('#telegram-attendance-form');if(attendanceForm){const fields=attendanceForm.elements;fields.enabled.onchange=()=>{fields.groupId.required=fields.enabled.checked};attendanceForm.onsubmit=async ev=>{ev.preventDefault();if(fields.enabled.checked&&!tgData.attendance?.connected){toast('Сначала подключите отдельного бота прихода и ухода');return}if(await mutate('telegram/attendance/settings',{enabled:fields.enabled.checked,groupId:fields.groupId.value.trim(),mode:fields.mode.value}))toast('Приём видео для смен сохранён')}}}
function confirmExtra(title,description,label,fn){open(title,`<div class="form"><p>${esc(description)}</p><button class="btn" id="extra-confirm">${label}</button></div>`);modal.querySelector('#extra-confirm').onclick=fn}
async function extraAct(d){try{switch(d.action){case'pay-kpi-visibility':await payrollVisibilitySettings();break;case'tga-excel-retry':if(await mutate('telegram/attendance/excel/retry',{employee:d.employee,snapshot:d.snapshot}))toast('Excel добавлен в очередь');break;case'tga-daily-send':{const r=tgData.dailyReports;confirmExtra('Отправить ежедневный отчёт',`Отчёт за ${r.day} получат лично: ${r.employees.filter(e=>r.recipients.includes(e.id)).map(e=>e.name).join(', ')}. Уже отправленные части не повторяются.`, 'Отправить отчёт',async()=>{if(await mutate('telegram/attendance/daily-reports/send',{day:r.day})){modal.close();toast('Отправка запущена. Статусы видны в таблице.')}});break}case'tga-daily-retry':if(await mutate('telegram/attendance/daily-reports/retry',{employee:d.employee,day:d.day}))toast('Повторная отправка запущена');break;case'tga-early-decision':open(d.status==='approved'?'Подтвердить разрешение раннего ухода':'Не подтверждать разрешение',`<form class="form"><p>Фактическое время и видео сохраняются. Уже начисленные деньги автоматически не изменяются.</p><label>Основание решения<textarea name="reason" required minlength="3" maxlength="500"></textarea></label><button class="btn">Сохранить решение</button></form>`);submitPay('telegram/attendance/early-exit/decision',{token:d.token,status:d.status});break;case'pay-detail':payDetail(d.employee);break;case'pay-history':await payrollHistory(d.employee);break;case'pay-terms':payrollPublishTerms(d.employee);break;case'pay-terms-all':payrollPublishTerms(null);break;case'pay-dispute':payrollDisputeDecision(d.id);break;case'pay-account':payAccount(d.employee);break;case'pay-entry':payEntry(d.employee);break;case'pay-job':payJob(d.employee,d.id);break;case'pay-approve-job':{const r=payRow(d.employee),j=r.jobs.find(x=>x.id===d.id),requestId=crypto.randomUUID();confirmExtra('Подтвердить выполненную работу',`${r.employee.name}: ${j.name} · ${cash(j.quantity)} ${j.unit} × ${cash(j.rate)} = ${cash(j.calculated)} ${r.account.currency}. Сумма будет начислена.`, 'Подтвердить выполнение',async()=>{if(await mutate('payroll/job/approve',{employee:d.employee,month:payMonth,id:d.id,requestId})){modal.close();toast('Работа начислена')}});break}case'pay-kpi':payKpi(d.employee,d.id);break;case'pay-settings':paySettings();break;case'pay-void':open('Отменить запись',`<form class="form"><p>Запись сохранится в истории, но перестанет влиять на остаток.</p><label>Причина отмены<textarea name="reason" required maxlength="300"></textarea></label><button class="btn danger">Подтвердить отмену</button></form>`);submitPay('payroll/void',{id:d.id});break;case'pay-late':case'pay-approve-kpi':{const late=d.action==='pay-late',r=payRow(d.employee),item=late?r.lateCandidates.find(x=>x.shift===d.shift):r.metrics.find(x=>x.id===d.id);const amount=late?item.amount:item.calculated;const requestId=crypto.randomUUID();confirmExtra(late?'Подтвердить штраф':'Начислить бонус KPI',`${r.employee.name}: ${cash(amount)} ${r.account.currency}. Эта сумма изменит остаток к выплате.`, 'Подтвердить',async()=>{if(await mutate(late?'payroll/late':'payroll/kpi/approve',{employee:d.employee,month:payMonth,shift:d.shift,id:d.id,requestId})){modal.close();toast('Подтверждено')}});break}case'tga-invite':await attendanceInvite(d.employee);break;case'tga-approve':{const b=(tgData.attendance?.bindings||[]).find(x=>x.employee===d.employee);if(!b)throw Error('Привязка не найдена');confirmExtra('Подтвердить для учёта смен',`${b.name} · Telegram ${b.username} · ID ${b.chat}. Проверьте, что аккаунт принадлежит этому сотруднику. Доступ к зарплатному боту не меняется.`, 'Подтвердить для смен',async()=>{if(await mutate('telegram/attendance/approve',{employee:d.employee})){modal.close();toast('Привязка для смен подтверждена')}});break}case'tga-unlink':confirmExtra('Отвязать от бота смен','Отметки этого аккаунта больше не будут приниматься. Сохранённые смены и доступ к зарплатному боту останутся.','Отвязать от смен',async()=>{if(await mutate('telegram/attendance/unlink',{employee:d.employee}))modal.close()});break;case'tga-disconnect':confirmExtra('Отключить бота прихода и ухода','Приём видео и ответы бота смен прекратятся. История смен и зарплатный бот продолжат работать.','Отключить бота смен',async()=>{if(await mutate('telegram/attendance/disconnect',{}))modal.close()});break;case'tg-refresh':await load();break;case'tg-invite':{const r=await api('telegram/invite',{employee:d.employee});open('Личная ссылка сотрудника',`<div class="form"><p>Передайте эту ссылку лично нужному сотруднику. Срок действия — 15 минут. Затем проверьте запрос на привязку в программе.</p><label>Ссылка<input readonly value="${esc(r.url)}" id="invite-url"></label><button class="btn" id="copy-invite">Скопировать</button></div>`);modal.querySelector('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(r.url);toast('Ссылка скопирована')}catch{modal.querySelector('#invite-url').select();toast('Скопируйте выделенную ссылку')}};break}case'tg-approve':{const b=tgData.bindings.find(x=>x.employee===d.employee);confirmExtra('Подтвердить сотрудника',`${b.name} · Telegram ${b.username} · ID ${b.chat}. Подтверждайте после проверки, что аккаунт принадлежит этому сотруднику.`, 'Подтвердить доступ',async()=>{if(await mutate('telegram/approve',{employee:d.employee})){modal.close();toast('Доступ к своим данным открыт')}});break}case'tg-unlink':confirmExtra('Отвязать Telegram','Сотрудник потеряет доступ через этот аккаунт. Финансовая история сохранится.','Отвязать',async()=>{if(await mutate('telegram/unlink',{employee:d.employee}))modal.close()});break;case'tg-disconnect':confirmExtra('Отключить бота','Ответы сотрудникам прекратятся. Данные и привязки сохранятся.','Отключить',async()=>{if(await mutate('telegram/disconnect',{}))modal.close()});break}}catch(e){toast(e.message)}}

function payJob(id,jid){const j=payRow(id).jobs.find(x=>x.id===jid);open(j?'Изменить работу':'Выполненная работа',`<form class="form"><label>Название работы<input name="name" required maxlength="100" value="${esc(j?.name||'')}" placeholder="Например, обработка поставки"></label><label>Единица измерения<input name="unit" required maxlength="30" value="${esc(j?.unit||'шт.')}" placeholder="шт., заказ, объект"></label><div class="split"><label>Количество<input name="quantity" type="number" min="0.01" step="0.01" required value="${cashInput(j?.quantity||100)}"></label><label>Цена за единицу, ${esc(payData.settings.currency)}<input name="rate" type="number" min="0.01" step="0.01" required value="${j?cashInput(j.rate):''}"></label></div><label>Дата выполнения<input name="date" type="date" required value="${j?.date||data.today}" max="${data.today}"></label><p class="help">Сумма = количество × цена. Сохраните запись, затем подтвердите выполнение в карточке сотрудника — только после этого она попадёт в заработок.</p><button class="btn">Сохранить работу</button></form>`);submitPay('payroll/job',{employee:id,month:payMonth,id:jid})}



async function attendanceInvite(employee){const r=await api('telegram/attendance/invite',{employee});open('Личная ссылка для бота смен',`<div class="form"><p>Передайте ссылку лично этому сотруднику. Он должен открыть её в боте прихода и ухода. Срок действия — 15 минут. Затем подтвердите привязку в таблице смен.</p><label>Ссылка бота смен<input readonly value="${esc(r.url)}" id="attendance-invite-url"></label><button class="btn" id="copy-attendance-invite">Скопировать</button></div>`);modal.querySelector('#copy-attendance-invite').onclick=async()=>{try{await navigator.clipboard.writeText(r.url);toast('Ссылка для смен скопирована')}catch{modal.querySelector('#attendance-invite-url').select();toast('Скопируйте выделенную ссылку')}}}

function videoRetryPanel(v){if(!v)return '';const labels={pending:'Запланирован повтор',running:'Обрабатывается',done:'Сохранено',failed:'Нужна проверка',expired:'Срок повторов истёк',cancelled:'Отменено'};return panel('Автоповтор видео · журнал обработки',`<p>При временной ошибке Telegram или хранилища бот делает до ${esc(v.limit)} попыток в течение ${esc(v.windowMinutes)} минут. Время отметки остаётся временем исходного видео. В очереди: <strong>${esc(v.pending)}</strong>.</p><p class="help">Ошибки графика, неверная привязка и повреждённые файлы требуют проверки. При окончательной ошибке сотрудник и назначенные ответственные получают личное сообщение.</p>${hrTable(['Сотрудник / видео','Попытки / статус','Этап / ошибка','Следующий повтор'],v.items.map(r=>[esc(r.name)+'<span class="sub">'+stamp(r.at)+' · '+(r.kind==='in'?'Приход':'Уход')+'</span>'+(/^[-]100[0-9]+$/.test(r.group_id)?'<a target="_blank" rel="noreferrer" href="https://t.me/c/'+r.group_id.slice(4)+'/'+Number(r.message_id)+'">Видео №'+Number(r.message_id)+'</a>':'Видео №'+Number(r.message_id)),esc(r.attempts)+' / '+esc(v.limit)+'<span class="sub">'+badge(labels[r.status]||r.status,r.status==='done'?'good':['failed','expired'].includes(r.status)?'bad':'warn')+'</span>',esc(r.phase||'—')+'<span class="sub">'+esc(r.error_code||'—')+'</span>',r.status==='pending'?stamp(r.next):'—']))}`)}

function geofencePanel(g){if(!g)return '';const names={inside:'Внутри зоны',outside:'Вне зоны / у границы','accuracy-missing':'Нет данных о точности','accuracy-poor':'Низкая точность'};return panel('Территория магазина · видео + геолокация',`<form class="form" id="attendance-geofence-form"><label><input name="enabled" type="checkbox" ${g.enabled?'checked':''}> Требовать геолокацию для каждого видео прихода и ухода</label><p>После видео сотрудник отправляет текущее местоположение через кнопку в личном чате бота в течение ${g.windowSeconds} секунд. Координаты в рабочую группу не публикуются. Время отметки берётся из видео.</p><label>Название магазина<input name="label" maxlength="120" value="${esc(g.label)}"></label><div class="row"><label>Широта<input name="latitude" type="number" min="-90" max="90" step="any" value="${esc(g.latitude??'')}"></label><label>Долгота<input name="longitude" type="number" min="-180" max="180" step="any" value="${esc(g.longitude??'')}"></label><label>Радиус, м<input name="radius" type="number" min="25" max="1000" required value="${g.radius}"></label><label>Максимальная погрешность GPS, м<input name="maxAccuracy" type="number" min="5" max="500" required value="${g.maxAccuracy}"></label></div><label>Ссылка на магазин в картах<input name="sourceUrl" type="url" maxlength="1500" value="${esc(g.sourceUrl)}"></label><label><input name="requireAccuracy" type="checkbox" ${g.requireAccuracy?'checked':''}> Отклонять геолокацию, если Telegram не сообщил точность</label><p class="help">Если точность известна, расстояние до магазина вместе с погрешностью должно помещаться в радиус. В помещении GPS может ошибаться. Telegram не гарантирует защиту от выбранной вручную точки или подмены GPS; это проверка переданных телефоном координат, а не постоянное слежение.</p><button class="btn">Сохранить территорию</button>${Number.isFinite(g.latitude)&&Number.isFinite(g.longitude)?'<a target="_blank" rel="noreferrer" href="https://yandex.uz/maps/?pt='+g.longitude+','+g.latitude+'&z=18&l=map">Посмотреть центр зоны</a>':''}</form><h3>Журнал геолокации · последние 30 проверок</h3>${hrTable(['Сотрудник / видео','Результат / источник','Расстояние / точность','Время / точка'],g.checks.map(c=>[esc(c.name)+'<span class="sub">Видео №'+Number(c.message_id)+'</span>',badge(names[c.result]||c.result,c.result==='inside'?'good':'warn')+'<span class="sub">'+(c.source==='telegram-mini-app'?'Мини-приложение':'Сообщение Telegram')+'</span>',Math.round(c.distance)+' м / '+(c.accuracy===null?'точность неизвестна':'±'+Math.round(c.accuracy)+' м'),esc(stamp(c.location_at))+(Number.isFinite(c.latitude)&&Number.isFinite(c.longitude)?'<span class="sub"><a target="_blank" rel="noreferrer" href="https://yandex.uz/maps/?pt='+c.longitude+','+c.latitude+'&z=18&l=map">Местоположение</a></span>':'')]))}`);}


let payWorkflowData=null,payWorkflowError='';
function payrollWorkflowPanel(){
 const w=payWorkflowData;if(!w)return payWorkflowError?panel('Условия KPI и вопросы по расчёту','<p class="notice">'+esc(payWorkflowError)+'</p>'):'';
 const employees=w.employees||[],summary=w.summary||{},disputes=employees.flatMap(e=>(e.disputes||[]).map(d=>({...d,name:e.name,employee:e.id})));
 return panel('Условия KPI и вопросы по зарплате',`<div class="metrics"><article><span>Условия опубликованы</span><strong>${Number(summary.termsPublished||0)}</strong></article><article><span>Ознакомились</span><strong>${Number(summary.termsAcknowledged||0)}</strong></article><article><span>Открытые вопросы</span><strong>${Number(summary.openDisputes||0)}</strong></article><article><span>Ожидается отметка о получении</span><strong>${Number(summary.pendingReceipts||0)}</strong></article></div><p class="help">Условия публикуются с текущей датой. Отметка сотрудника означает ознакомление, а подтверждение получения денег не заменяет кассовый или банковский документ.</p><div class="row">${button('Опубликовать условия всем','pay-terms-all')}</div>${hrTable(['Сотрудник','Условия / ознакомление','Действия'],employees.map(e=>{const term=e.terms?.current;return [esc(e.name),term?'Версия '+esc(term.version)+' · '+(term.acknowledged?'Ознакомился':'Ожидает ознакомления')+(term.sourceChanged?'<span class="sub notice">Условия расчёта изменились. Требуется публикация новой версии.</span>':''):'Не опубликованы',button('Опубликовать условия','pay-terms',`data-employee="${esc(e.id)}"`)+button('История должности и ставки','pay-history',`data-employee="${esc(e.id)}"`)];}))}<h3>Вопросы по конкретным суммам</h3>${disputes.length?hrTable(['Сотрудник / основание','Вопрос','Статус / решение'],disputes.map(d=>[esc(d.name)+'<span class="sub">'+esc(d.month)+' · '+esc(d.referenceType)+' · '+esc(d.referenceId)+'</span>',esc(d.question),esc(({open:'Открыт',reviewing:'На проверке',resolved:'Решён',rejected:'Отклонён'})[d.status]||d.status)+(d.decision?'<span class="sub">'+esc(d.decision)+'</span>':'')+button('Рассмотреть','pay-dispute',`data-id="${esc(d.id)}"`)])):'<p class="help">Вопросов по расчёту за этот месяц нет.</p>'}`);
}
async function payrollWorkflowLoad(){payWorkflowError='';try{payWorkflowData=await api('payroll/workflows?month='+payMonth);}catch(error){payWorkflowData=null;payWorkflowError=error.message||'Условия KPI временно недоступны';}}
function payrollPublishTerms(employee){
 const person=payData.rows.find(r=>r.employee.id===employee),current=payWorkflowData?.employees?.find(e=>e.id===employee)?.terms?.current;
 open(employee?'Опубликовать условия KPI · '+esc(person?.employee.name||'Сотрудник'):'Опубликовать условия KPI всем',`<form class="form"><p>Период ${esc(payMonth)}. Сотрудник увидит действующую базу, показатели, планы, веса и максимальную премию. Сохраняется новая версия условий с фактической датой публикации.</p><p class="notice">Публикация условий не начисляет зарплату и не ставит отметку ознакомления за сотрудника.</p><label>Основание публикации / изменения<textarea name="reason" required minlength="3" maxlength="500"></textarea></label><button class="btn">Опубликовать условия</button><p role="status"></p></form>`);const form=modal.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const b=form.querySelector('button');b.disabled=true;try{await api('payroll/workflows/terms-publish',{month:payMonth,...(employee?{employee,expectedVersion:current?.version||0}:{all:true}),reason:form.elements.reason.value});modal.close();await load();toast('Условия опубликованы. Ознакомление ожидается от сотрудников.');}catch(error){form.querySelector('[role=status]').textContent=error.message;b.disabled=false;}};
}
function payrollDisputeDecision(id){
 const d=payWorkflowData?.employees?.flatMap(e=>(e.disputes||[]).map(d=>({...d,name:e.name}))).find(d=>d.id===id);if(!d)return;
 open('Вопрос по расчёту · '+esc(d.name),`<form class="form"><p>${esc(d.question)}</p><p class="help">${esc(d.month)} · ${esc(d.referenceType)} · ${esc(d.referenceId)}</p><label>Статус<select name="status"><option value="reviewing">На проверке</option><option value="resolved">Решён</option><option value="rejected">Отклонён</option></select></label><label>Ответ сотруднику<textarea name="reason" required minlength="3" maxlength="2000">${esc(d.decision||'')}</textarea></label><p class="notice">Ответ на вопрос не меняет денежные записи. Корректировка расчёта оформляется отдельно через финансовое согласование.</p><button class="btn">Сохранить решение</button><p role="status"></p></form>`);const form=modal.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const b=form.querySelector('button');b.disabled=true;try{await api('payroll/workflows/dispute-decide',{id,version:d.version,status:form.elements.status.value,reason:form.elements.reason.value});modal.close();await load();toast('Решение сохранено');}catch(error){form.querySelector('[role=status]').textContent=error.message;b.disabled=false;}};
}
async function payrollHistory(employee){
 try{const h=await api('payroll/history?employee='+encodeURIComponent(employee)),rows=h.events||h.rows||h.history||[],person=h.employee,canEditRole=!!data.user?.admin||data.user?.permissions?.staff==='write';
  open('История должности и ставки · '+esc(person?.name||payRow(employee).employee.name),`<div class="form"><p>Изменение действует с указанной даты. История прошлых месяцев сохраняется. Будущая должность отмечается как запланированная.</p>${hrTable(['Действует с','Изменение','Основание / статус'],rows.map(r=>[esc(r.effectiveDate),r.kind==='role'?esc(r.role):Number.isSafeInteger(r.base)?cash(r.base)+' '+esc(r.currency):'—',esc(r.reason||'')+'<span class="sub">'+esc(({scheduled:'Запланировано',active:'Действует',historical:'История'})[r.status]||r.status||'')+'</span>']))}<form id="pay-role-history"><fieldset ${canEditRole?'':'disabled'}><h3>Изменить должность с даты</h3><label>Должность<input name="role" required maxlength="120" value="${esc(person?.role||'')}"></label><label>Дата начала<input name="effectiveDate" type="date" required value="${esc(data.today)}"></label><label>Основание<textarea name="reason" required minlength="3" maxlength="500"></textarea></label><button class="btn">Сохранить изменение должности</button></fieldset>${canEditRole?'':'<p class="help">Изменение должности доступно администратору или пользователю с правом редактирования сотрудников.</p>'}<p role="status"></p></form>${button('Изменить месячную базу','pay-account',`data-employee="${esc(employee)}"`)}</div>`);extraBind(modal);const form=modal.querySelector('#pay-role-history');form.onsubmit=async event=>{event.preventDefault();if(!canEditRole)return;const b=form.querySelector('button');b.disabled=true;try{await api('payroll/history/role',{employee,role:form.elements.role.value,effectiveDate:form.elements.effectiveDate.value,reason:form.elements.reason.value,version:h.version});modal.close();await load();toast('Датированное изменение сохранено');}catch(error){form.querySelector('[role=status]').textContent=error.message;b.disabled=false;}};
 }catch(error){toast(error.message||'Не удалось загрузить историю');}
}

// KPI visibility is independent of payroll calculation and the six payroll tools.
async function payrollVisibilityLoad(){
 payKpiVisibility=null;payKpiVisibilityError='';
 if(typeof data==='undefined'||!data?.user?.admin)return;
 try{payKpiVisibility=await api('payroll/kpi-visibility');}catch(error){payKpiVisibilityError=error.message||'Настройки показа KPI временно недоступны';}
}
function payrollVisibilityButton(){
 if(typeof data==='undefined'||!data?.user?.admin)return '';
 const c=payKpiVisibility,status=c?'Кабинет: '+(c.web?'включён':'выключен')+' · Бот: '+(c.bot?'включён':'выключен'):payKpiVisibilityError||'Загрузка настроек';
 return '<span class="pay-kpi-visibility">'+button('Показ KPI сотрудникам','pay-kpi-visibility')+'<span class="sub">'+esc(status)+'</span></span>';
}
async function payrollVisibilitySettings(){
 if(typeof data==='undefined'||!data?.user?.admin)return;
 if(!payKpiVisibility)await payrollVisibilityLoad();
 if(!payKpiVisibility){toast(payKpiVisibilityError);return;}
 const c=payKpiVisibility;
 open('Показ KPI сотрудникам',`<form class="form" id="pay-kpi-visibility-form"><label class="check"><input type="checkbox" name="web" ${c.web?'checked':''}> Показывать KPI в личном кабинете и Mini App</label><label class="check"><input type="checkbox" name="bot" ${c.bot?'checked':''}> Показывать KPI в зарплатном боте</label><p class="help">Переключатели управляют процентами, планом и фактом KPI и проектами премий. Подтверждённые начисления, зарплата и выплаты сохраняются. Администратор продолжает видеть расчёты.</p><label>Основание изменения<textarea name="reason" required minlength="3" maxlength="500"></textarea></label><button class="btn">Сохранить показ KPI</button><p role="status"></p></form>`);
 const form=modal.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await api('payroll/kpi-visibility',{version:c.version,web:form.elements.web.checked,bot:form.elements.bot.checked,reason:form.elements.reason.value});modal.close();await load();toast('Настройки показа KPI сохранены');}catch(error){form.querySelector('[role=status]').textContent=error.message;button.disabled=false;}};
}
